#!/usr/bin/env node
/**
 * Differential harness: runs the reference build and the Node port over the
 * same argv and reports any divergence in stdout, stderr, or exit status.
 *
 * Cases are read from a JSON file: an array of argv arrays.
 *
 *   node tools/difftest.mjs cases.json
 */

import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const HERE = dirname(fileURLToPath(import.meta.url));
const REFERENCE = '/workspace/dataset/test8_executable';
const PORT = resolve(HERE, '..', 'test8.mjs');

/** @param {string[]} argv */
function runReference(argv) {
  const r = spawnSync(REFERENCE, argv, { encoding: 'buffer' });
  return { out: r.stdout, err: r.stderr, code: r.status };
}

/** @param {string[]} argv */
function runPort(argv) {
  const r = spawnSync(process.execPath, [PORT, ...argv], { encoding: 'buffer' });
  return { out: r.stdout, err: r.stderr, code: r.status };
}

const show = (buf) => JSON.stringify(buf.toString('utf8'));

const casesPath = process.argv[2];
const cases = JSON.parse(readFileSync(casesPath, 'utf8'));

let failures = 0;
for (const argv of cases) {
  const a = runReference(argv);
  const b = runPort(argv);

  const same =
    a.code === b.code && Buffer.compare(a.out, b.out) === 0 && Buffer.compare(a.err, b.err) === 0;

  if (!same) {
    failures++;
    console.log('MISMATCH argv=' + JSON.stringify(argv));
    if (a.code !== b.code) console.log(`  exit: py=${a.code} js=${b.code}`);
    if (Buffer.compare(a.out, b.out) !== 0) {
      console.log(`  stdout py=${show(a.out)}`);
      console.log(`  stdout js=${show(b.out)}`);
    }
    if (Buffer.compare(a.err, b.err) !== 0) {
      console.log(`  stderr py=${show(a.err)}`);
      console.log(`  stderr js=${show(b.err)}`);
    }
  }
}

console.log(`\n${cases.length - failures}/${cases.length} cases match`);
process.exit(failures === 0 ? 0 : 1);
