#!/usr/bin/env node
/**
 * Fuzz generator for the command-line PARSING surface.
 *
 * Emits a JSON array of argv arrays on stdout, built from a vocabulary of
 * tokens chosen to stress CPython's argparse: abbreviations, `=`-attached
 * values, the `--` separator, negative-number-looking values, unknown options,
 * empty strings, and repeated options.
 *
 *   node tools/fuzzargv.mjs [count] [seed] > cases.json
 *
 * Deterministic: the same (count, seed) pair always yields the same corpus.
 */

/** xorshift128 -- a small deterministic PRNG so runs are reproducible. */
function makeRandom(seed) {
  let a = seed >>> 0 || 0x9e3779b9;
  let b = 0x243f6a88;
  let c = 0xb7e15162;
  let d = 0x85ebca6b;
  return function next() {
    const t = a ^ (a << 11);
    a = b;
    b = c;
    c = d;
    d = (d ^ (d >>> 19) ^ t ^ (t >>> 8)) >>> 0;
    return d / 0x100000000;
  };
}

/**
 * The stress vocabulary named by the task, plus a handful of neighbours that
 * probe the same boundaries from the other side.
 */
const VOCAB = [
  // the real options
  '--payload',
  '--secret',
  '--help',
  '-h',

  // separators and degenerate tokens
  '--',
  '-',
  '',
  '---',

  // unknown / option-shaped
  '-x',
  '-p',
  '-s',

  // negative-number lookalikes
  '-1',
  '-1.5',
  '-.5',
  '-0',
  '-12345',
  '-1a',

  // abbreviations, including ambiguity candidates
  '--pay',
  '--p',
  '--s',
  '--se',
  '--h',
  '--sec',
  '--payloa',
  '--hel',

  // attached values
  '--payload=v',
  '--secret=',
  '--payload=--',
  '--payload=',
  '--secret=s',
  '--help=1',
  '--h=1',
  '-h=1',
  '--p=v',
  '--payload=-x',
  '--payload=a=b',

  // near misses on the option names
  '--payloadx',
  '--PAYLOAD',
  '-payload',
  '--secretx',
  '--SECRET',
  '-secret',
  '--payload-',
  '--_payload',

  // plain values / positionals
  'positional',
  'a b',
  ' -x',
  'value',
  'v',
  'x',
  'y',
  'z',
  '0',
  'a',
  'b',
  'foo bar',
  '=',
  '=v',
  'a=b',
];

/**
 * Build one random argv of length 0..8.
 *
 * Half the draws are uniform over the vocabulary; the other half are biased so
 * that plausible-but-wrong command lines (option immediately followed by
 * another option, an option repeated, a value stranded before an option) show
 * up far more often than uniform sampling would produce them.
 */
function makeCase(rand) {
  const length = Math.floor(rand() * 9); // 0..8
  /** @type {string[]} */
  const argv = [];

  const pick = () => VOCAB[Math.floor(rand() * VOCAB.length)];

  // Shapes that seed the array with something option-like before the random
  // tail, so long argvs are not almost-always dominated by junk.
  const shape = rand();
  if (shape < 0.18) {
    argv.push(rand() < 0.5 ? '--payload' : '--secret');
  } else if (shape < 0.3) {
    argv.push('--payload', pick());
  } else if (shape < 0.38) {
    argv.push('--secret', pick());
  } else if (shape < 0.46) {
    // A complete, valid pair with random junk appended -- isolates
    // "unrecognized arguments" from "required arguments".
    argv.push('--payload', 'p', '--secret', 's');
  } else if (shape < 0.52) {
    argv.push('--');
  }

  while (argv.length < length) argv.push(pick());
  argv.length = Math.min(argv.length, 8);
  return argv;
}

/**
 * A hand-written spine of cases that random sampling reaches only rarely but
 * that sit exactly on the boundaries the task calls out.
 */
function structuredCases() {
  /** @type {string[][]} */
  const out = [];
  const push = (...argv) => out.push(argv);

  // required vs unrecognized precedence
  push();
  push('positional');
  push('-x');
  push('--payloadx');
  push('positional', '-x', '--payloadx');
  push('--payload', 'p', 'positional');
  push('--payload', 'p', '--secret', 's', 'positional');
  push('--payload', 'p', '--secret', 's', '-x');
  push('--payload', 'p', '--secret', 's', 'a', 'b', 'c');
  push('--payload', 'p', '-x', '--secret', 's');
  push('-x', '--payload', 'p', '--secret', 's');
  push('-x', '-1', '--payload', 'p', '--secret', 's');
  push('--payload', 'p', '--secret', 's', '-x', '-y', 'z');
  push('a b', '--payload', 'p', '--secret', 's');
  push(' -x', '--payload', 'p', '--secret', 's');

  // help short-circuit against every kind of error
  push('-h');
  push('--help');
  push('--h');
  push('--hel');
  push('-h', '-x');
  push('-x', '-h');
  push('--payload', '-h');
  push('-h', '--payload');
  push('--payload', 'p', '-h');
  push('-h', 'positional');
  push('positional', '-h');
  push('--', '-h');
  push('-h', '--');
  push('--help=1');
  push('-h', '--help');
  push('--ambiguousnothing', '-h');

  // '--' placement
  push('--');
  push('--', '--');
  push('--', '--payload', 'p', '--secret', 's');
  push('--payload', 'p', '--secret', 's', '--');
  push('--payload', 'p', '--', '--secret', 's');
  push('--payload', '--', '--secret', 's');
  push('--payload', '--', 'p', '--secret', 's');
  push('--payload=--', '--secret', 's');
  push('--payload', 'p', '--secret', 's', '--', 'x');
  push('--payload', 'p', '--secret', 's', '--', '--');
  push('--payload', 'p', '--', '--', '--secret', 's');
  push('--', '-x');
  push('---');
  push('--', '---');

  // '-' and negative numbers
  push('-');
  push('--payload', '-', '--secret', 's');
  push('--payload', '-1', '--secret', 's');
  push('--payload', '-1.5', '--secret', 's');
  push('--payload', '-.5', '--secret', 's');
  push('--payload', '-1a', '--secret', 's');
  push('--payload', '-0', '--secret', 's');
  push('-1', '--payload', 'p', '--secret', 's');
  push('-.5', '--payload', 'p', '--secret', 's');
  push('-1.5');

  // empty strings
  push('');
  push('', '');
  push('--payload', '', '--secret', '');
  push('', '--payload', 'p', '--secret', 's');
  push('--payload=', '--secret=');

  // abbreviation resolution / ambiguity
  push('--pay', 'p', '--sec', 's');
  push('--p', 'p', '--s', 's');
  push('--payloa', 'p', '--secre', 's');
  push('--se', 's', '--pay', 'p');
  push('--p=v', '--s=k');
  push('--pay=v', '--se=k');
  push('-p', 'v');
  push('-s', 'v');
  push('-payload', 'v');
  push('-secret', 'v');
  push('--PAYLOAD', 'v');
  push('--payload-', 'v');
  push('--_payload', 'v');
  push('--', '--pay');

  // repeated options
  push('--payload', 'a', '--payload', 'b', '--secret', 's');
  push('--secret', 'a', '--secret', 'b', '--payload', 'p');
  push('--payload', 'a', '--payload');
  push('--payload=1', '--payload=2', '--secret=3');
  push('--payload', '--payload', '--secret', 's');
  push('--secret', '--secret', '--payload', 'p');

  // missing values
  push('--payload');
  push('--secret');
  push('--payload', '--secret');
  push('--secret', '--payload');
  push('--payload', 'p', '--secret');
  push('--secret', 's', '--payload');
  push('--payload', '--secret', 's');
  push('--p');
  push('--s');
  push('--pay');

  // odd '=' shapes
  push('=');
  push('=v');
  push('a=b');
  push('--=v');
  push('--payload=a=b', '--secret', 's');
  push('--payload=-x', '--secret', 's');
  push('-h=1');
  push('--h=1');

  return out;
}

const count = Number.parseInt(process.argv[2] ?? '3000', 10);
const seed = Number.parseInt(process.argv[3] ?? '20260809', 10);
const rand = makeRandom(seed);

/** @type {string[][]} */
const cases = structuredCases();
const seen = new Set(cases.map((c) => JSON.stringify(c)));

// Random draws, de-duplicated so casesRun counts distinct argvs.
let guard = 0;
while (cases.length < count && guard < count * 60) {
  guard++;
  const argv = makeCase(rand);
  const key = JSON.stringify(argv);
  if (seen.has(key)) continue;
  seen.add(key);
  cases.push(argv);
}

process.stdout.write(JSON.stringify(cases));

#!/usr/bin/env node
/**
 * Parallel differential runner.
 *
 * Runs the reference build and the Node port over every argv in a JSON corpus,
 * comparing stdout bytes, stderr bytes, and exit code. Cases run with bounded
 * concurrency because the reference build costs ~250ms of process start-up.
 *
 *   node tools/pardiff.mjs cases.json [concurrency] > report.json
 */

import { spawn } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';
import { cpus } from 'node:os';

const HERE = dirname(fileURLToPath(import.meta.url));
const REFERENCE = '/workspace/dataset/test8_executable';
const PORT = resolve(HERE, '..', 'test8.mjs');

/** @returns {Promise<{out: Buffer, err: Buffer, code: number|null, signal: string|null}>} */
function run(cmd, args) {
  return new Promise((res, rej) => {
    const child = spawn(cmd, args, { stdio: ['ignore', 'pipe', 'pipe'] });
    /** @type {Buffer[]} */ const out = [];
    /** @type {Buffer[]} */ const err = [];
    child.stdout.on('data', (d) => out.push(d));
    child.stderr.on('data', (d) => err.push(d));
    child.on('error', rej);
    child.on('close', (code, signal) =>
      res({ out: Buffer.concat(out), err: Buffer.concat(err), code, signal }),
    );
  });
}

const casesPath = process.argv[2];
const concurrency = Number.parseInt(process.argv[3] ?? '', 10) || Math.max(4, cpus().length * 2);
/** @type {string[][]} */
const cases = JSON.parse(readFileSync(casesPath, 'utf8'));

/** @type {object[]} */
const mismatches = [];
let done = 0;
let cursor = 0;

async function worker() {
  for (;;) {
    const i = cursor++;
    if (i >= cases.length) return;
    const argv = cases[i];
    const [a, b] = await Promise.all([run(REFERENCE, argv), run(process.execPath, [PORT, ...argv])]);
    done++;

    const sameOut = Buffer.compare(a.out, b.out) === 0;
    const sameErr = Buffer.compare(a.err, b.err) === 0;
    const sameCode = a.code === b.code && a.signal === b.signal;

    if (!(sameOut && sameErr && sameCode)) {
      mismatches.push({
        argv,
        ref: {
          out: a.out.toString('base64'),
          err: a.err.toString('base64'),
          code: a.code,
          signal: a.signal,
        },
        port: {
          out: b.out.toString('base64'),
          err: b.err.toString('base64'),
          code: b.code,
          signal: b.signal,
        },
        diff: [!sameOut && 'stdout', !sameErr && 'stderr', !sameCode && 'exit'].filter(Boolean),
      });
    }
    if (done % 250 === 0) process.stderr.write(`  ${done}/${cases.length}\n`);
  }
}

await Promise.all(Array.from({ length: concurrency }, worker));

process.stderr.write(`ran ${done}/${cases.length}, ${mismatches.length} mismatches\n`);
process.stdout.write(JSON.stringify({ casesRun: done, mismatches }, null, 2));

