#!/usr/bin/env node
/**
 * Exhaustive enumeration of every argv of length 1..3 over a curated
 * high-signal token subset. Random sampling covers breadth; this covers every
 * ordering interaction among the tokens that actually change parser state.
 *
 *   node tools/exhaustargv.mjs > cases-exhaustive.json
 */

const TOKENS = [
  '--payload',
  '--secret',
  '-h',
  '--',
  '-',
  '',
  '-x',
  '-1',
  '--pay',
  '--p',
  '--payload=v',
  'positional',
];

/** @type {string[][]} */
const cases = [[]];

for (const a of TOKENS) cases.push([a]);
for (const a of TOKENS) for (const b of TOKENS) cases.push([a, b]);
for (const a of TOKENS) for (const b of TOKENS) for (const c of TOKENS) cases.push([a, b, c]);

process.stdout.write(JSON.stringify(cases));
